package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.SamlIdpSsoUrlVO;

class SamlIdpSsoUrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of saml idp sso url of tenant login provider")
  void test_saml_idp_sso_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    SamlIdpSsoUrlValueHolder<Object> value = new SamlIdpSsoUrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.samlIdpSsoUrl("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getSamlIdpSsoUrlValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getSamlIdpSsoUrl().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.samlIdpSsoUrlNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getSamlIdpSsoUrlValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getSamlIdpSsoUrl().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of saml idp sso url of tenant login provider")
  void test_saml_idp_sso_url_value_holder_assign_value_object() {
    Object holder = new Object();
    SamlIdpSsoUrlValueHolder<Object> value = new SamlIdpSsoUrlValueHolder<>(holder);
    SamlIdpSsoUrlVO vo = SamlIdpSsoUrlVO.from("one");
    Assertions.assertFalse(value.getSamlIdpSsoUrlValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.samlIdpSsoUrl(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSamlIdpSsoUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.samlIdpSsoUrl(Optional.empty()));
    Assertions.assertFalse(value.getSamlIdpSsoUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.samlIdpSsoUrl(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSamlIdpSsoUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of saml idp sso url of tenant login provider against the original")
  void test_saml_idp_sso_url_value_holder_read() {
    Object holder = new Object();
    SamlIdpSsoUrlValueHolder<Object> value = new SamlIdpSsoUrlValueHolder<>(holder);
    SamlIdpSsoUrlVO vo = SamlIdpSsoUrlVO.from("one");
    SamlIdpSsoUrlVO other = SamlIdpSsoUrlVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getSamlIdpSsoUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSamlIdpSsoUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSamlIdpSsoUrl(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.samlIdpSsoUrl(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSamlIdpSsoUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSamlIdpSsoUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of saml idp sso url of tenant login provider")
  void test_saml_idp_sso_url_value_holder_unset() {
    Object holder = new Object();
    SamlIdpSsoUrlValueHolder<Object> value = new SamlIdpSsoUrlValueHolder<>(holder);
    SamlIdpSsoUrlVO vo = SamlIdpSsoUrlVO.from("one");
    value.samlIdpSsoUrl(vo);
    Assertions.assertSame(holder, value.unsetSamlIdpSsoUrlIfMatches("samlIdpSsoUrl_other"));
    Assertions.assertTrue(value.getSamlIdpSsoUrlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSamlIdpSsoUrlIfMatches("samlIdpSsoUrl"));
    Assertions.assertFalse(value.getSamlIdpSsoUrlValue().isPresent(),
        "The field name must clear the value");
    value.samlIdpSsoUrl(vo);
    Assertions.assertSame(holder, value.unsetSamlIdpSsoUrl());
    Assertions.assertFalse(value.getSamlIdpSsoUrlValue().isPresent(), "Unset must clear the value");
  }
}
